1:part of 'fah.dart';
2:
3:Future<void> _runApp(List<String> args) async {
4:  final packageVersion = _packageVersion();
5:  _applyProviderFilterEnv();
6:  // Platform-aware chord display (issue #809): Option/Cmd labels on macOS.
7:  tuiKeyHintDarwin = Platform.isMacOS;
8:  // `fa serve [--a2a|--bridge] [--port N] [--token T]` — the parser does
9:  // not know the serve forms, so they are intercepted before CliArgs
10:  // parsing: serve-specific flags are stripped from the parsed args and
11:  // kept for the late interception below (after model/key resolution).
12:  final serve = splitServeA2aArgs(args);
13:  // `fa wire-serve [--port N] [--stdio] [--token T]` (issue #1103) — the
14:  // headless AWP server. Intercepted like serve: the parser does not know
15:  // the form, and the words must never reach prompt parsing. Flag errors
16:  // (--stdio with --port, a bad --port) are LOUD startup failures (E2) —
17:  // never a silent fallback to another mode.
18:  final WireServeArgs wireServe;
19:  try {
20:    wireServe = splitWireServeArgs(args);
21:  } on FormatException catch (error) {
22:    _fail(
23:      'usage: fa wire-serve [--port N] [--stdio] [--token T]\n'
24:      '${error.message}',
25:    );
26:  }
27:  // `fa hub serve [--port N]` — a local DAP hub, no agent boot
28:  // (docs/dap.md §8.1). Intercepted on the raw args BEFORE the serve
29:  // marker check below (`hub serve` contains the word "serve" but is a
30:  // different command): the words must never reach prompt parsing.
31:  if (args.isNotEmpty && args.first == 'hub') {
32:    exit(await runHubCommand(args.sublist(1)));
33:  }
34:  // `fa dap start|stop|status [--port N]` — the one-step local DAP hub
35:  // (issue #304): probe/spawn/enroll/stop with no agent boot, same raw-
36:  // args interception as `fa hub serve`.
37:  if (args.isNotEmpty && args.first == 'dap') {
38:    exit(await runDapCommand(args.sublist(1)));
39:  }
40:  final serveMarkerCount =
41:      (serve.serveA2a ? 1 : 0) + (serve.serveBridge ? 1 : 0);
42:  if (serveMarkerCount != 1 && args.contains('serve')) {
43:    _fail(
44:      'usage: fa serve --a2a [--port N] [--token T] | '
45:      'fa serve --bridge [--port N] [--token T]',
46:    );
47:  }
48:
49:  late final CliArgs parsed;
50:  try {
51:    parsed = switch (parseCliArgs(
52:      wireServe.wireServe ? wireServe.cliArgs : serve.cliArgs,
53:    )) {
54:      CliArgsHelp() => _exitWithUsage(packageVersion),
55:      CliArgsVersion(:final output) => _exitWithVersion(
56:        packageVersion,
57:        output: output,
58:      ),
59:      final CliArgs cliArgs => cliArgs,
60:    };
61:  } on CliArgsException catch (error) {
62:    _fail(error.message);
63:  }
64:
65:  // gh-1556: the ONE session deadline clock. The host env seeds it
66:  // (missing/invalid = feature off, silent); `--timer`/`--deadline`
67:  // override the env (later wins); `/timer` adjusts it live. An invalid
68:  // FLAG spec is the user's own words — a usage error, never a silently
69:  // wrong clock.
70:  final SessionDeadline sessionDeadline;
71:  try {
72:    sessionDeadline = resolveSessionDeadline(
73:      envValue: Platform.environment[deadlineEpochMsEnvVar],
74:      flagSpec: parsed.timer ?? parsed.deadline,
75:    );
76:  } on FormatException catch (error) {
77:    // Not dead code: parseCliArgs's `_validateDeadlineFlag` only checks
78:    // the spec's SHAPE — a well-formed but PAST epoch (e.g.
79:    // `--deadline 1893456000000`) passes there and throws here, at
80:    // `SessionDeadline.setEpochMs`. Keep this catch; it defends that one
81:    // narrow path.
82:    _fail('invalid --timer/--deadline: ${error.message}');
83:  }
84:
85:  // Quick self-management commands, intercepted before prompt resolution:
86:  // `fa update` swaps in the latest release binary; `fa uninstall` removes
87:  // the binary + PATH entry (and ~/.fah on a second confirmation).
88:  if (parsed.positionals.length == 1 && parsed.prompt == null) {
89:    switch (parsed.positionals.single) {
90:      case 'update':
91:        exit(await runSelfUpdate(currentVersion: packageVersion));
92:      case 'uninstall':
93:        exit(await runSelfUninstall());
94:    }
95:  }
96:  // `fa trajectory <verb> [sessionId] [--json] [--at N]` — read-only
97:  // trajectory views over a stored session; intercepted before prompt
98:  // resolution so the verb words never become a prompt.
99:  final trajectory = parsed.trajectory;
100:  if (trajectory != null) {
101:    exit(await _runTrajectoryCommand(trajectory, parsed));
102:  }
103:
104:  // `fa ext <verb> ...` — headless JS extension management, intercepted
105:  // like trajectory: no agent boot, the exit code propagates.
106:  final ext = parsed.ext;
107:  if (ext != null) {
108:    final extEnv = LocalExecutionEnv(cwd: parsed.cwd ?? Directory.current.path);
109:    exit(
110:      await runExtCliCommand(
111:        ext,
112:        io: _TerminalCliIO(headless: true),
113:        env: extEnv,
114:        projectDir: extEnv.cwd,
115:        userDir: _homeDir(),
116:      ),
117:    );
118:  }
119:
120:  // `fa jsr widget:test|widget:screenshot …` — the js_widget_runtime agent
121:  // CLI pass-through (gh-1033), intercepted like trajectory: no agent
122:  // boot. The child's stdout/stderr stream straight through and its exit
123:  // code propagates (CI-usable); platform bits (PATH) come from the
124:  // process, the only dart:io layer here.
125:  final jsr = parsed.jsr;
126:  if (jsr != null) {
127:    final jsrEnv = LocalExecutionEnv(cwd: parsed.cwd ?? Directory.current.path);
128:    exit(
129:      await runJsrCliCommand(
130:        jsr,
131:        io: SinkJsrCliIo(
132:          onStdout: stdout.write,
133:          onStderr: stderr.write,
134:          onNote: stderr.writeln,
135:        ),
136:        env: jsrEnv,
137:        projectDir: jsrEnv.cwd,
138:        pathEnv: Platform.environment['PATH'] ?? '',
139:        pathListSeparator: Platform.isWindows ? ';' : ':',
140:        windowsQuoting: Platform.isWindows,
141:      ),
142:    );
143:  }
144:  // `fa session list [--json] [--flat]` (issue #198) — the tree-grouped
145:  // session listing, intercepted like trajectory: no agent boot.
146:  // `fa session repair <sessionId|path> [--dry-run]` (gh-1073) — ledger
147:  // surgery on a bloated session file, also without booting the agent.
148:  final sessionList = parsed.sessionList;
149:  if (sessionList != null) {
150:    final io = _TerminalCliIO(headless: true);
151:    final listEnv = LocalExecutionEnv(
152:      cwd: parsed.cwd ?? Directory.current.path,
153:    );
154:    final sessionRoot = parsed.sessionRoot ?? _defaultSessionRoot();
155:    if (sessionList.verb == 'repair') {
156:      exit(
157:        await runSessionRepairCliCommand(
158:          write: io.write,
159:          writeln: io.writeln,
160:          env: listEnv,
161:          sessionRoot: sessionRoot,
162:          sessionId: sessionList.repairTarget,
163:          dryRun: sessionList.dryRun,
164:          presenceStore: FileSessionPresenceStore(
165:            env: listEnv,
166:            root: sessionRoot,
167:          ),
168:        ),
169:      );
170:    }
171:    exit(
172:      await runSessionListCliCommand(
173:        write: io.write,
174:        writeln: io.writeln,
175:        env: listEnv,
176:        sessionRoot: sessionRoot,
177:        cwd: listEnv.cwd,
178:        json: sessionList.json,
179:        flat: sessionList.flat,
180:      ),
181:    );
182:  }
183:
184:  // JS extension bootstrap (.fa/bootstrap.yaml, project then user): every
185:  // normal start applies it idempotently before the REPL or headless run;
186:  // E15 soft-fail lines go to stderr. FA_EXT_BOOTSTRAP_STRICT=1 makes a
187:  // bootstrap failure fatal instead.
188:  try {
189:    await applyBootstrapIfPresent(
190:      io: _TerminalCliIO(headless: parsed.isHeadless),
191:      env: LocalExecutionEnv(cwd: parsed.cwd ?? Directory.current.path),
192:      projectDir: parsed.cwd ?? Directory.current.path,
193:      userDir: _homeDir(),
194:      strict: _envTruthy('FA_EXT_BOOTSTRAP_STRICT'),
195:    );
196:  } on Object catch (error) {
197:    _fail('ext bootstrap failed: $error');
198:  }
199:
200:  // Headless prompt resolution: --prompt-file read as UTF-8 verbatim
201:  // (missing/unreadable = usage error); -p verbatim; a first positional
202:  // naming an existing file inlines text files (.md/.markdown/.txt) or
203:  // attaches other files as a path reference; anything else is plain
204:  // prompt text.
205:  final String? headlessPrompt;
206:  try {
207:    headlessPrompt = resolveHeadlessPrompt(
208:      prompt: parsed.prompt,
209:      promptFile: parsed.promptFile,
210:      positionals: parsed.positionals,
211:    );
212:  } on CliArgsException catch (error) {
213:    _fail(error.message);
214:  }
215:
216:  // `fa config check|path|get|set` runs BEFORE loadCliConfig: check must
217:  // be able to diagnose exactly the broken config that would abort boot
218:  // (issue #29). homeDir may be null — the service reports the global
219:  // scope honestly.
220:  final earlyConfigCmd = parsed.config;
221:  if (earlyConfigCmd != null && earlyConfigCmd.verb != 'export-providers') {
222:    exit(
223:      await runConfigServiceCommand(
224:        earlyConfigCmd,
225:        io: _TerminalCliIO(headless: true),
226:        env: LocalExecutionEnv(cwd: Directory.current.path),
227:        homeDir: homeDirectory(),
228:      ),
229:    );
230:  }
231:
232:  final home = homeDirectory();
233:  if (home == null || home.isEmpty) {
234:    _fail('cannot resolve home directory; pass --session-root');
235:  }
236:  late final CliConfig saved;
237:  try {
238:    saved = loadCliConfig(home);
239:  } on ConfigException catch (error) {
240:    _fail('invalid ~/.fah/config.yaml: ${error.message}');
241:  }
242:  // Provider watchdog overrides (`providerTimeouts:` section): process-wide,
243:  // read by the adapters' connect/idle watchdogs on every request. The
244:  // FA_PROVIDER_TIMEOUT_SECONDS env value folds in over the section
245:  // (issue #1036: non-streaming fetch bound; env wins for CI runners).
246:  try {
247:    providerTimeoutsOverride = applyProviderTimeoutEnvOverride(
248:      saved.providerTimeouts,
249:      Platform.environment['FA_PROVIDER_TIMEOUT_SECONDS'],
250:    );
251:  } on ConfigException catch (error) {
252:    _fail(error.message);
253:  }
254:  // Per-provider+model capability overrides (`models.overrides`, gh-1426):
255:  // process-wide, consulted by every model build (roles chains, the legacy
256:  // single model, custom definitions) — the resolver's top layer.
257:  modelCapabilityOverrides = saved.models?.overrides;
258:  // Per-provider stall-recovery tuning (issue #1398): registry entries
259:  // declaring `connectTimeoutMs`/`streamIdleTimeoutMs` seed the tuning
260:  // table the watchdogs read per request URL. No entries → the table
261:  // stays empty and every watchdog keeps today's exact value.
262:  seedProviderTuning(
263:    customProviders: saved.customProviders,
264:    customModels: saved.models?.custom,
265:    roleRefs: [
266:      for (final chain
267:          in saved.modelRoles?.roles.values ?? const <List<ModelRef>>[])
268:        ...chain,
269:    ],
270:  );
271:
272:  // Auto-update boot hook (issue #1377, `auto_update:` config): `off` is
273:  // zero network; `notify` runs one bounded check and prints a
274:  // once-per-process banner; `on` applies + restarts into the successor
275:  // BEFORE the session boots — applied → exit(0), the successor inherits
276:  // stdio + this argv and resumes the session through its own --session
277:  // flag. Help/version and the update/uninstall quick commands exited
278:  // above; serve/wire-daemon runs are skipped (a daemon must not restart
279:  // itself under connected clients), and `fa config export-providers`
280:  // (intercepted below) is not a session boot either.
281:  final autoUpdateNotify = AutoUpdateNotify();
282:  // The banner is best-effort: once the TUI owns the terminal a late
283:  // stderr line would garble a frame, so the probe drops it instead
284:  // (issue #1377 review r4).
285:  var autoUpdateTuiOwnsScreen = false;
286:  switch (bootUpdateAction(
287:    mode: saved.autoUpdate,
288:    serveOrDaemon:
289:        serve.serveA2a ||
290:        serve.serveBridge ||
291:        wireServe.wireServe ||
292:        parsed.config != null,
293:  )) {
294:    case BootUpdateAction.none:
295:      break;
296:    case BootUpdateAction.notifyCheck:
297:      // Background probe: the boot never waits on it — the banner prints
298:      // WHEN the answer lands (a dead endpoint just stays silent; the
299:      // 3 s bound keeps a hung socket from printing late into a live
300:      // TUI). stderr — the same pre-TUI boot-notice channel as the
301:      // config warnings above.
302:      unawaited(() async {
303:        // The probe OWNS its client: `.timeout` abandons the in-flight
304:        // request at the bound, and closing here (finally, always) is
305:        // what actually releases the socket — not the inner finally,
306:        // which only runs when the abandoned fetch itself settles.
307:        final probe = http.Client();
308:        try {
309:          final latest = await fetchLatestTag(client: probe)
310:              .timeout(const Duration(seconds: 3), onTimeout: () => null);
311:          if (latest != null &&
312:              compareVersions(latest, packageVersion) > 0 &&
313:              !autoUpdateTuiOwnsScreen) {
314:            final banner = autoUpdateNotify.banner(latest);
315:            if (banner != null) stderr.writeln(banner);
316:          }
317:        } on Object catch (_) {
318:          // Best-effort probe: a hostile/unreachable network must be
319:          // INVISIBLE (no banner), never a crash (issue #1377 review r4).
320:        } finally {
321:          probe.close();
322:        }
323:      }());
324:    case BootUpdateAction.applyAndExit:
325:      final outcome = await applyUpdate(
326:        currentVersion: packageVersion,
327:        launchArgs: args,
328:      );
329:      switch (outcome) {
330:        case ApplyUpdateOutcome.applied:
331:          exit(0);
332:        case ApplyUpdateOutcome.upToDate:
333:          break;
334:        case ApplyUpdateOutcome.refusedDevRun:
335:          stderr.writeln('fa: auto update unavailable for source runs');
336:        case ApplyUpdateOutcome.unsupportedPlatform:
337:          break; // The engine swapped and printed the restart hint.
338:        case ApplyUpdateOutcome.convergenceGuard:
339:          stderr.writeln(
340:            'fa: auto update paused — the release is not resolving '
341:            'through this channel yet; continuing on v$packageVersion',
342:          );
343:        case _:
344:          // Never crash the boot: one warn, then continue on the current
345:          // binary (restartFailed keeps the already-swapped new binary).
346:          stderr.writeln(
347:            'fa: auto update failed (${outcome.name}) — '
348:            'continuing on v$packageVersion',
349:          );
350:      }
351:  }
352:
353:  // Session image registry (`images:` section, issue #171): process-wide,
354:  // read inside the agent loop's request build. Default: on.
355:  imageRegistryConfig = saved.images ?? const ImageRegistryConfig();
356:
357:  // `fa config export-providers` — needs the loaded config (saved
358:  // providers + key names); check|path|get|set already ran above.
359:  final configCmd = parsed.config;
360:  if (configCmd != null) {
361:    final exportKeys = SecureKeyCache(platformSecureKeyStore());
362:    await exportKeys.preload(secureKeyPreloadNames(saved, baseUrl: null));
363:    exit(
364:      await runProviderExportCommand(
365:        configCmd,
366:        io: _TerminalCliIO(headless: true),
367:        env: LocalExecutionEnv(cwd: Directory.current.path),
368:        entries: saved.customProviders,
369:        secureRead: exportKeys.read,
370:      ),
371:    );
372:  }
373:
374:  late final ({
375:    CliArgs args,
376:    String provider,
377:    EnvProviderPreconfig? faPreconfig,
378:    String? unknownSavedProvider,
379:    String? incompatibleSavedEndpoint,
380:  })
381:  cliStartup;
382:  try {
383:    cliStartup = resolveEffectiveCliArgs(
384:      parsed,
385:      saved,
386:      env: Platform.environment,
387:    );
388:  } on ConfigException catch (error) {
389:    _fail(error.message);
390:  }
391:  final effective = cliStartup.args;
392:  var provider = cliStartup.provider;
393:  final faPreconfig = cliStartup.faPreconfig;
394:
395:  // gh-760: a persisted provider id no version knows must never brick the
396:  // boot. The config is shared with surfaces the CLI does not control
397:  // (the app, the extension, older/newer versions); the bad value gets a
398:  // loud named warning here (value, file, fallback taken, likely version
399:  // skew) and the known fallback provider takes over. The config file is
400:  // NOT modified — warn, don't mutate.
401:  if (cliStartup.unknownSavedProvider case final unknown?) {
402:    stderr.writeln(
403:      'warning: unknown provider "$unknown" in $home/.fah/config.yaml - '
404:      'written by a newer app/CLI version? falling back to '
405:      '"$provider" (the config was not modified; run /provider or edit '
406:      'the file to switch)',
407:    );
408:  }
409:  // gh-760 (review): a persisted provider/baseUrl PAIR an endpoint-locked
410:  // kind cannot serve (codex pointed at a stale foreign endpoint by a
411:  // partial write) degrades like an unknown id - the key gate would
412:  // otherwise refuse the boot with self-contradictory guidance.
413:  if (cliStartup.incompatibleSavedEndpoint case final conflict?) {
414:    stderr.writeln(
415:      'warning: saved provider "$conflict" only works with its own '
416:      'default endpoint - the saved baseUrl "${effective.baseUrl}" in '
417:      '$home/.fah/config.yaml is not servable by it; falling back to '
418:      '"$provider" (the config was not modified; run /provider or edit '
419:      'the file to switch)',
420:    );
421:  }
422:
423:  final cwd = effective.cwd ?? Directory.current.path;
424:  final sessionRoot = effective.sessionRoot ?? _defaultSessionRoot();
425:  // The execution env shared by the CLI config (tools, session storage),
426:  // the presence store (live-session heartbeats) and the per-folder model
427:  // state IO. Mutable cwd: a resumed session re-points it (see _loadSession).
428:  final cliEnv = LocalExecutionEnv(cwd: cwd);
429:
430:  // Per-folder model memory: restore the model/provider triple last used
431:  // in THIS folder — a `/model` switch in another workspace must not leak
432:  // in across restarts. Explicit per-launch declarations win: --model,
433:  // --provider, --base-url, or an FA_PROVIDER_* env preconfig.
434:  final folderState = await loadFolderModelState(
435:    cliEnv,
436:    sessionsRoot: sessionRoot,
437:    cwd: cwd,
438:  );
439:  final applyFolderState =
440:      folderState != null &&
441:      folderModelStateApplies(
442:        modelExplicit: parsed.model != null,
443:        providerExplicit: parsed.providerExplicit,
444:        baseUrlExplicit: parsed.baseUrl != null,
445:        hasProviderPreconfig: faPreconfig != null,
446:      );
447:  // gh-760: the folder state is written by the same shared-config family
448:  // — validate its provider kind the same way. An unrecognizable kind
449:  // gets a named warning and the state file is ignored (never a boot
450:  // throw); every catalog name/kind resolves by construction. The restore
451:  // takes the RESOLVED spec's KIND (review): a state file carrying a
452:  // catalog name must not leak the raw name into the stream factory.
453:  final folderSpec = applyFolderState
454:      ? resolveCliProviderSpec(folderState.providerKind)
455:      : null;
456:  final state = folderState;
457:  // gh-760 (review): the same provider/baseUrl PAIR judgement as the saved
458:  // config restore — an endpoint-locked kind over a foreign state baseUrl
459:  // is not servable; the state file is ignored with a named warning.
460:  final folderEndpointConflict =
461:      state != null &&
462:      folderSpec != null &&
463:      folderSpec.endpointLocked &&
464:      state.baseUrl != null &&
465:      state.baseUrl != folderSpec.defaultBaseUrl;
466:  final folderStateUsable =
467:      applyFolderState && folderSpec != null && !folderEndpointConflict;
468:  if (state != null && applyFolderState && !folderStateUsable) {
469:    stderr.writeln(
470:      folderEndpointConflict
471:          ? 'warning: saved folder model state pairs '
472:                '"${state.providerKind}" with a foreign baseUrl '
473:                '"${state.baseUrl}" - the kind only works with its '
474:                'own default endpoint '
475:                '(${folderModelStatePath(sessionsRoot: sessionRoot, cwd: cwd)})'
476:                ' — ignoring it and keeping "$provider"'
477:          : 'warning: saved folder model state names unknown provider '
478:                '"${state.providerKind}" '
479:                '(${folderModelStatePath(sessionsRoot: sessionRoot, cwd: cwd)}) — '
480:                'ignoring it and keeping "$provider"',
481:    );
482:  }
483:  // gh-1000 (AC1): the state's saved-provider NAME pins WHICH saved entry
484:  // serves the restored model — two entries can share one endpoint and
485:  // modelId, and endpoint-keyed resolution would pick the first config
486:  // match (possibly the other account's key → 401). A name that no
487:  // longer resolves degrades to endpoint-keyed resolution with a note
488:  // (E1 — the model is kept). The resolution lives in fah_boot_restore.dart
489:  // (the pin logic's one testable home; round-3 review).
490:  final folderPinned = resolveBootFolderPin(
491:    state: folderStateUsable ? state : null,
492:    entries: saved.customProviders,
493:  );
494:  if (folderPinned.note != null) {
495:    stderr.writeln('note: ${folderPinned.note}');
496:  }
497:  final folderPinnedEntry = folderPinned.entry;
498:  final applyFolderModel = applyFolderState && folderStateUsable;
499:  if (applyFolderModel) {
500:    provider = folderSpec.kind;
501:  }
502:  final baseUrl = applyFolderModel ? folderState.baseUrl : effective.baseUrl;
503:
504:  final model = applyFolderModel
505:      ? buildCliDefaultModel(
506:          provider,
507:          modelId: folderState.modelId,
508:          baseUrl: folderState.baseUrl,
509:          // A saved custom-provider entry carrying this endpoint's
510:          // authHeader (issue #964) must survive the restore.
511:          authHeader: authHeaderForBaseUrl(
512:            saved.customProviders,
513:            folderState.baseUrl,
514:          ),
515:          thinkingLevel: faPreconfig?.thinkingLevel,
516:        )
517:      : _buildModel(
518:          effective,
519:          input: faPreconfig?.input,
520:          thinkingLevel: faPreconfig?.thinkingLevel,
521:          // gh-1471 D4: a declared capability pair (bench's kimi mapping)
522:          // reaches the booted model; undeclared stays null — the catalog
523:          // layers decide, byte-identical to before.
524:          contextWindow: faPreconfig?.contextWindow,
525:          maxTokens: faPreconfig?.maxTokens,
526:        );
527:
528:  // Initial cube (fa_cube Phase 1): --cube-config path > --cube name > the
529:  // project `.fah/config.yaml` `cube:` section > the saved user `cube:`
530:  // section (each config section only when enabled). A broken manifest is
531:  // a hard error — a requested cube must never fail open into an
532:  // unconfined run.
533:  String? cubeSource;
534:  CubeSpec? cubeSpec;
535:  try {
536:    cubeSource = resolveStartupCubeSource(
537:      flagConfigPath: parsed.cubeConfigPath,
538:      flagName: parsed.cubeName,
539:      project: loadProjectCubeSettings(cwd),
540:      user: saved.cube,
541:    );
542:    final isPath = cubeSource?.contains('/') ?? false;
543:    cubeSpec = await CubeResolver.resolve(
544:      env: cliEnv,
545:      path: isPath ? cubeSource : null,
546:      name: isPath ? null : cubeSource,
547:      homeDir: home,
548:    );
549:  } on ConfigException catch (error) {
550:    _fail(error.message);
551:  }
552:
553:  // Compaction engine (issue #148, default flip #287): `--compaction-engine`
554:  // flag > the project `.fah/config.yaml` `compaction:` section > the saved
555:  // user `compaction:` section > structured (2.0 default; classic is the
556:  // legacy rollback). Strict parse errors are hard startup errors (a typo
557:  // must never silently downgrade the engine).
558:  final compactionEngine = resolveCompactionEngine(
