5:/// Reads the package version with four fallbacks so compiled binaries stay
6:/// accurate: `-DFA_VERSION=` baked at compile time (legacy AOT builds), then
7:/// a `version.txt` file alongside the `dart build cli` bundle, then the
8:/// `pubspec.yaml` next to the executable (source runs), then the constant.
9:String _packageVersion() {
10:  const fromEnv = String.fromEnvironment('FA_VERSION');
11:  if (fromEnv.isNotEmpty) return fromEnv;
12:  try {
13:    // Platform.resolvedExecutable always returns the full canonical path,
14:    // even when the binary was invoked via a bare name or relative path.
15:    // Platform.script may return a relative path on some platforms, which
16:    // makes exeDir = cwd instead of the binary's real directory.
17:    final exePath = Platform.resolvedExecutable;
18:    final exeDir = File(exePath).parent;
19:    final bundleRoot = exeDir.parent;
20:    // Try bundle/version.txt first (dart build cli layout).
21:    final versionFile = File('${bundleRoot.path}/version.txt');
22:    if (versionFile.existsSync()) {
23:      final v = versionFile.readAsStringSync().trim();
24:      if (v.isNotEmpty) return v;
25:    }
26:    // Try <exe_dir>/version.txt (installer layout: version.txt next to fa).
27:    final dirVersionFile = File('${exeDir.path}/version.txt');
28:    if (dirVersionFile.existsSync()) {
29:      final v = dirVersionFile.readAsStringSync().trim();
30:      if (v.isNotEmpty) return v;
31:    }
32:    // Source run: pubspec.yaml sits two levels up from bin/.
33:    final pubspec = File('${bundleRoot.path}/pubspec.yaml');
34:    final doc = yaml.loadYaml(pubspec.readAsStringSync()) as Map;
35:    final value = doc['version'];
36:    if (value is String && value.isNotEmpty) return value;
37:  } on Object {
38:    // Fall back to the compile-time constant when nothing is available.
39:  }
40:  return _fallbackVersion;
41:}
