35:  /// Attaches the ttsr controller when the yaml section ships rules
36:  /// (issue #1078 AC3) — the CLI's exact pair ([TtsrManager] over
37:  /// [TtsrController]) watching this agent's stream. Public: this is the
38:  /// documented app surface the settings registry's `ttsrRules` appRef
39:  /// names. Injections persist through the same crash-safe chain the
40:  /// transcript uses ([AgentServicePersistence]); the closure reads the
41:  /// LIVE session, so a session switch re-points the sink without a
42:  /// re-attach.
43:  void attachAppConfigTtsr(AppFahSections? appConfig) {
44:    final ttsr = appConfig?.ttsr;
45:    if (ttsr == null || !ttsr.settings.enabled) return;
46:    final manager = TtsrManager(settings: ttsr.settings);
47:    for (final rule in ttsr.rules) {
48:      manager.addRule(rule);
49:    }
50:    for (final warning in manager.warnings) {
51:      AppLog.i('ttsr', warning);
52:    }
53:    if (!manager.hasRules()) return;
54:    // The controller self-subscribes (it owns its unsubscribe); no other
55:    // lifecycle is needed — session switches ride the live sink closure.
56:    TtsrController(
57:      agent: _agent,
58:      manager: manager,
59:      sink: TtsrSessionSink(
60:        session: () => _session,
61:        persistedMessageCount: () => _persistedCount,
62:        persistMessage: (message) async {
63:          final session = _session;
64:          if (session == null) return;
65:          await session.appendMessage(message);
66:          _persistedCount++;
67:        },
68:        persistInjection: (content, ruleNames) async {
69:          final session = _session;
70:          if (session == null) return;
71:          await session.appendCustomMessageEntry(
72:            customType: ttsrInjectionCustomType,
73:            content: content,
74:            display: false,
75:            details: {'rules': ruleNames},
76:          );
77:          await session.appendCustomEntry(
78:            customType: ttsrInjectionRecordType,
79:            data: {'rules': ruleNames},
80:          );
81:          _persistedCount++;
82:        },
83:      ),
84:      onTriggered: (rules) => AppLog.i(
85:        'ttsr',
86:        'rule violation: '
87:            '${rules.map((rule) => rule.name).join(', ')} — retrying',
88:      ),
89:      onWarning: (message) => AppLog.i('ttsr', message),
90:    );
91:  }
