14:  /// Picks the stream function for [config]'s backend: the on-device
15:  /// bridges for `webllm`/`gemma`/`transformers_js`, the HTTP adapters
16:  /// otherwise. HTTP adapters get the live session id as the prompt-cache
17:  /// affinity key (resolved lazily — the session is created after this).
18:  StreamFunction _streamFunctionFor(AgentConfig config) {
19:    if (config.providerKind == webLlmProviderKind) {
20:      return webLlmStreamFunction(createWebLlmService());
21:    }
22:    if (config.providerKind == gemmaProviderKind) {
23:      return gemmaStreamFunction(createGemmaService());
24:    }
25:    if (config.providerKind == transformersJsProviderKind) {
26:      return transformersJsStreamFunction(createTransformersJsService());
27:    }
28:    // CodeMie: the cookie rides in model.headers (set by toModel); pass an
29:    // empty key so the adapter skips `Authorization: Bearer`.
30:    final apiKey = isCodeMieProvider(config.baseUrl) ? '' : config.apiKey;
31:    // Issue #327: provider auth failures surface the owning row's name —
32:    // a bare `401: No cookie auth credentials found` gives the user no
33:    // idea WHICH provider row to fix. On-device bridges keep raw errors.
34:    return decorateAuthErrors(
35:      providerStreamFunction(
36:        config.providerKind,
37:        apiKey,
38:        sessionId: () => _session?.cachedId,
39:      ),
40:      () => _connectionDisplayName(
41:        _providerRegistry,
42:        config.baseUrl,
43:      ), // null = pass-through, no registry row to name.
44:    );
45:  }
