39:  /// Writes every buffered request-capture record as context-omitted
40:  /// CustomRecords, in chain order (blobs first, summary last — the replay
41:  /// walk expects the summary as the step's predecessor). // ponytail: N
42:  /// buffered requests flush as one batch — the replay walk keys by chain
43:  /// position, so a throttled multi-request burst can coalesce onto one
44:  /// step; per-request keys if that matters.
45:  Future<void> _flushRequestSummaries(Session session) async {
46:    if (_pendingRequestRecords.isEmpty) return;
47:    final pending = List.of(_pendingRequestRecords);
48:    _pendingRequestRecords.clear();
49:    for (final (:customType, :data) in pending) {
50:      if (customType == _pendingModelChangeMarker) {
51:        // Issue #440: the System row for this request-context version —
52:        // a real ModelChangeRecord through the same session API the
53:        // model-switch flow uses, so replay projects the row the
54:        // following summary stamps (F7a). Never a custom record.
55:        await session.appendModelChange(
56:          provider: _agent.state.model.provider,
57:          modelId: _agent.state.model.id,
58:        );
59:        continue;
60:      }
61:      await session.appendCustomEntry(customType: customType, data: data);
62:    }
63:  }
