65:  /// Rebuilds the trajectory ledger from the active session branch
66:  /// (session open/switch/external reload); windowed callers pass the
67:  /// VIEW branch so paged-in history feeds the ledger without a storage
68:  /// walk.
69:  Future<void> _rebuildTrajectory({List<SessionRecord>? records}) async {
70:    final session = _session;
71:    if (session == null) return;
72:    final gen = _loadGeneration;
73:    _trajectory.reset();
74:    final sw = Stopwatch()..start();
75:    final branch = records ?? await session.getBranch();
76:    if (gen != _loadGeneration || !identical(session, _session)) return;
77:    // One bulk snapshot (issue #262): the whole backfill is synchronous
78:    // O(n) work — no intermediate snapshots exist to render, and the old
79:    // per-append materialization was the O(n²) open stall. With no awaits
80:    // inside, the fold is atomic for the event loop: a generation bump or
81:    // session swap lands either fully before or fully after it (the #199
82:    // E1 guard, now checked around the single synchronous block).
83:    _trajectory.appendAll(branch);
84:    AppLog.i(
85:      'trajectory',
86:      'backfill: ${branch.length} records, '
87:          '${_trajectory.latest.records.length} rows in '
88:          '${sw.elapsedMilliseconds}ms',
89:    );
90:  }
