316:  /// Creates an [AgentCli]. [streamFunction] overrides the provider adapter
317:  /// (used in tests); otherwise one is built from
318:  /// [AgentCliConfig.providerKind] and [AgentCliConfig.apiKey].
319:  AgentCli({
320:    required this.config,
321:    required CliIO io,
322:    StreamFunction? streamFunction,
323:    this.prompt = 'fa> ',
324:    bool useColor = false,
325:    bool useTui = false,
326:    this._version = '0.0.0',
327:    this.environment = const {},
328:    MarkdownSurface? markdownSurface,
329:    DateTime Function()? waitingClock,
330:    Future<void> Function(Duration)? waitingSleep,
331:    SigintPolicy? sigintPolicy,
332:  }) : io = useTui && io.supportsRawMode ? _TuiCliIO(io) : io,
333:       _style = _Style(enabled: useColor),
334:       _markdownSurface = markdownSurface ?? const MarkdownSurface(),
335:       _waitingClock = waitingClock ?? DateTime.now,
336:       _waitingSleep =
337:           waitingSleep ?? ((Duration d) => Future<void>.delayed(d)),
338:       _useTui = useTui && io.supportsRawMode,
339:       sigintPolicy = sigintPolicy ?? SigintPolicy(),
340:       _deadline = config.deadline ?? SessionDeadline() {
341:    // Sleep prevention (issue #325): null runner (tests, web) → none.
342:    _powerAssertions = sessionPowerAssertions(config, this.io.writeln);
343:    _env = CwdOverrideEnv(config.env);
344:    _modes = builtInAgentModes(_env.cwd, overrides: config.promptOverrides);
345:    _currentMode = _modes[config.initialMode] ?? _modes['code']!;
346:    _providerKind = config.providerKind;
347:    _apiKey = config.apiKey;
348:    _liveLoadMode = config.loadMode;
349:    // The boot-restored saved provider entry (the folder state's name pin,
350:    // gh-1000): the CLI starts with that entry active — its key slot
351:    // serves the restored model and its name shows in the status bar.
352:    _activeCustomName = config.activeCustomName;
353:    // The theme emitters' color profile: the surface's pinned palette
354:    // (the host's single resolution, issue #774) wins; otherwise styled
355:    // iff this session styles at all (TUI or colored line mode), with
356:    // NO_COLOR / TERM=dumb degrading to plain output (issue #279 AC7).
357:    FaThemeController.instance.profile =
358:        _markdownSurface.profile ??
359:        detectThemeProfile(
360:          ansiSupported: useTui || useColor,
361:          environment: environment,
362:        );
363:    // Boot theme: async — user themes load through the FileSystem seam
