47:/// A host's declared extension: named tools + an explicit per-profile
48:/// matrix state (E6).
49:final class HostExtension {
50:  /// Registrant id — E7 collision reports name both sides; keep it the
51:  /// thing a host user would recognize (`cli-plugins`, `yoclip`).
52:  final String name;
53:
54:  /// The tools contributed on profiles where the extension is `on`.
55:  final List<AgentTool> tools;
56:
57:  /// The matrix declaration: profile name → state. Every built-in profile
58:  /// (the keys of `builtInProfiles`) MUST be present — E6, no implicit
59:  /// default. Extra keys are custom profiles; they are validated at wire
60:  /// time (a state must exist for whatever the host actually wires).
61:  final Map<String, CapabilityState> profileStates;
62:
63:  /// Validates and builds. Throws [HostProfileViolation] on an E6 gap
64:  /// (missing built-in profile, blank reason, a transport state — tool
65:  /// extensions have no transport dimension), an empty name, or an
66:  /// empty/duplicate tool id.
67:  HostExtension({
68:    required this.name,
69:    List<AgentTool> tools = const [],
70:    required Map<String, CapabilityState> profileStates,
71:  }) : tools = List.unmodifiable(tools),
72:       profileStates = Map.unmodifiable(profileStates) {
73:    if (name.trim().isEmpty) {
74:      throw const HostProfileViolation(
75:        'HostExtension name must not be blank (E7 names registrants — '
76:        'they need a real id).',
77:      );
78:    }
79:    final missing = builtInProfiles.keys
80:        .where((profile) => !profileStates.containsKey(profile))
81:        .toList();
82:    if (missing.isNotEmpty) {
83:      throw HostProfileViolation(
84:        'HostExtension "$name" declares no state for built-in profile(s) '
85:        '${missing.map((m) => '"$m"').join(', ')} — declare every built-in '
86:        'profile explicitly (E6: there is no implicit default).',
87:      );
88:    }
89:    for (final entry in profileStates.entries) {
90:      if (entry.value is CapabilityTransportState) {
91:        throw HostProfileViolation(
92:          'HostExtension "$name" declares a transport state for profile '
93:          '"${entry.key}" — tool extensions have no transport dimension; '
94:          'declare on or off(reason).',
95:        );
96:      }
97:      if (entry.value.reason case final reason? when reason.trim().isEmpty) {
98:        throw HostProfileViolation(
99:          'HostExtension "$name" is off on "${entry.key}" without a reason '
100:          '— off is never silent (E8).',
101:        );
102:      }
103:    }
104:    final seen = <String>{};
105:    for (final tool in tools) {
106:      if (tool.name.trim().isEmpty) {
107:        throw HostProfileViolation(
108:          'HostExtension "$name" contributes a tool with a blank id.',
109:        );
110:      }
111:      if (!seen.add(tool.name)) {
112:        throw HostProfileViolation(
113:          'HostExtension "$name" contributes "${tool.name}" twice — the '
114:          'builder rejects duplicate ids at build time (E7).',
115:        );
116:      }
117:    }
118:  }
119:
120:  /// The declared state for [profileName], or null when the profile is a
121:  /// custom one this extension does not declare (validated at wire time).
122:  CapabilityState? stateFor(String profileName) => profileStates[profileName];
123:}
