126:/// stack, or the off reason (E8) for the host's UI.
127:final class WiredHostExtension {
128:  /// The declared extension this outcome belongs to.
129:  final HostExtension extension;
130:
131:  /// The tools wired on this profile; empty when hidden.
132:  final List<AgentTool> tools;
133:
134:  /// Non-null when the extension is hidden on this profile (E8): the
135:  /// profile's declared off reason, never empty.
136:  final String? hiddenReason;
137:
138:  /// True when the extension is hidden on this profile.
139:  bool get isHidden => hiddenReason != null;
