65:/// Fails when [config.modelId] is owned by a registry row OTHER than the
66:/// one serving [config.baseUrl] — the #327 fingerprint: an OpenRouter
67:/// model id riding a CodeMie (or any other) endpoint sends the request to
68:/// an endpoint/auth pair that never heard of the model.
69:String? _modelRowMismatch(ProviderRegistry? registry, AgentConfig config) {
70:  if (registry == null) return null;
71:  final entries = registry.providers;
72:  final serving = entries.where((e) => e.baseUrl == config.baseUrl);
73:  if (serving.any((e) => e.modelId == config.modelId)) return null;
74:  final owners = entries
75:      .where((e) => e.modelId == config.modelId && e.baseUrl != config.baseUrl)
76:      .toList();
77:  if (owners.isEmpty) return null;
78:  // Same-host rows are ONE provider infrastructure — path variants,
79:  // duplicates, self-hosted gateways (issue #327 review MAJOR 3): a model
80:  // id reused between them is the endpoint's own business, not a
81:  // mixed-row assembly. Only a DIFFERENT host owning the id stays
82:  // suspicious (the #327 fingerprint: an OpenRouter-format id riding a
83:  // CodeMie endpoint).
84:  final host = _hostOf(config.baseUrl);
85:  if (owners.every((e) => _hostOf(e.baseUrl) == host)) return null;
86:  final servingName =
87:      _connectionDisplayName(registry, config.baseUrl) ?? config.baseUrl;
88:  final ownerNames = owners.map((e) => e.name).toSet().join("', '");
89:  // When the endpoint has no registry row the display name IS the url -
90:  // appending it again reads "url (url)" (issue #327 relay-path guard).
91:  final servingRef = servingName == config.baseUrl
92:      ? servingName
93:      : '$servingName (${config.baseUrl})';
94:  return "Model ${config.modelId} belongs to provider '$ownerNames' "
95:      '(${owners.first.baseUrl}), active connection is $servingRef. '
96:      'Pick the model from the SAME provider row as the endpoint you '
97:      'are connecting to.';
