142:StreamFunction decorateAuthErrors(
143:  StreamFunction inner,
144:  String? Function() label,
145:) {
146:  final authFailure = RegExp(
147:    r'^40[13]:|^[45]\d\d:?.*(unauthorized|api key|credentials|sign in)',
148:    caseSensitive: false,
149:  );
150:  return (model, context, {cancelToken}) {
151:    final owner = label();
152:    final stream = inner(model, context, cancelToken: cancelToken);
153:    if (owner == null || owner.isEmpty) return stream;
154:    final controller = AssistantMessageEventStream();
155:    Future<void> pump() async {
156:      try {
157:        await for (final event in stream) {
158:          var outgoing = event;
159:          if (event is ErrorEvent) {
160:            final text = event.error.errorMessage ?? '';
161:            if (authFailure.hasMatch(text.trim())) {
162:              final patched = event.error.copyWith(
163:                errorMessage: '[$owner] $text',
164:              );
165:              outgoing = ErrorEvent(reason: event.reason, error: patched);
166:            }
167:          }
168:          controller.push(outgoing);
169:        }
170:      } on Object catch (error) {
171:        controller.push(
172:          ErrorEvent(
173:            reason: StopReason.error,
174:            error: AssistantMessage(
175:              content: const [],
176:              api: model.api,
177:              provider: model.provider,
178:              model: model.id,
179:              usage: Usage.zero,
180:              stopReason: StopReason.error,
181:              errorMessage: '[internal] $error',
182:              timestamp: DateTime.now(),
183:            ),
184:          ),
185:        );
186:      }
187:      controller.end();
188:    }
189:
190:    unawaited(pump());
191:    return controller;
192:  };
193:}
