142:/// [AsrTranscriber] over a Whisper-compatible `/audio/transcriptions`
143:/// endpoint (OpenAI, Groq, or a local whisper.cpp server) — the same wire
144:/// shape as the harness's `transcribe_audio` tool.
145:final class WhisperTranscriber implements AsrTranscriber {
146:  /// Creates a transcriber for [config]; [httpClient] is injectable for
147:  /// tests.
148:  const WhisperTranscriber({required this.config, this.httpClient});
149:
150:  /// Endpoint configuration (key, base URL, model id).
151:  final TranscribeAudioConfig config;
152:
153:  /// Optional HTTP client override (tests).
154:  final http.Client? httpClient;
155:
156:  @override
157:  Future<String> transcribe({
158:    required Uint8List bytes,
159:    required String filename,
160:    String? language,
161:  }) async {
162:    final baseUrl = config.baseUrl ?? 'https://api.openai.com/v1';
163:    final request =
164:        http.MultipartRequest(
165:            'POST',
166:            Uri.parse('$baseUrl/audio/transcriptions'),
167:          )
168:          ..headers['authorization'] = 'Bearer ${config.apiKey}'
169:          ..fields['model'] = config.modelId
170:          ..fields['response_format'] = 'json'
171:          ..files.add(
172:            // The file part's content type stays application/octet-stream;
173:            // the endpoints key off the filename extension instead.
174:            http.MultipartFile.fromBytes('file', bytes, filename: filename),
175:          );
176:    final hint = (language == null || language.isEmpty)
177:        ? config.language
178:        : language;
179:    if (hint != null && hint.isNotEmpty) {
180:      request.fields['language'] = hint;
181:    }
182:
183:    final client = httpClient ?? http.Client();
184:    final http.Response response;
185:    try {
186:      response = await http.Response.fromStream(await client.send(request));
187:    } finally {
188:      if (httpClient == null) client.close();
189:    }
190:
191:    if (response.statusCode != 200) {
192:      throw StateError(
193:        'Transcription failed (HTTP ${response.statusCode}): '
194:        '${response.body.trim()}',
195:      );
196:    }
197:
198:    // `response_format=json` answers `{"text": "..."}`; whisper.cpp variants
199:    // may answer with the bare transcript, so fall back to the raw body.
200:    try {
201:      final decoded = jsonDecode(response.body);
202:      if (decoded is Map<String, dynamic> && decoded['text'] is String) {
203:        return (decoded['text'] as String).trim();
204:      }
205:    } on FormatException {
206:      // Not JSON: fall through to the raw body.
207:    }
208:    return response.body.trim();
209:  }
210:}
